//! The running total of generated bytes, and the result zip.

use super::failure::{GenerationFailure, Kind};
use super::plan::PlanTest;
use std::fs::File;
use std::io::{Seek, Write};
use std::path::Path;
use zip::write::SimpleFileOptions;

/// Inputs and answers together, uncompressed, against the plan's `max_total_bytes`.
pub struct Budget {
    used: u64,
    max: u64,
}

impl Budget {
    pub fn new(max: u64) -> Self {
        Budget { used: 0, max }
    }

    pub fn charge(&mut self, bytes: u64) -> Result<(), GenerationFailure> {
        self.used = self.used.saturating_add(bytes);
        if self.used > self.max {
            return Err(GenerationFailure::job(
                Kind::OutputLimit,
                format!("inputs and answers exceed {} bytes in total", self.max),
            ));
        }
        Ok(())
    }
}

fn add_file(
    writer: &mut zip::ZipWriter<impl Write + Seek>,
    entry: &str,
    source: &Path,
) -> Result<(), GenerationFailure> {
    writer.start_file(
        entry,
        SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated),
    )?;
    std::io::copy(&mut File::open(source)?, writer)?;
    Ok(())
}

/// One deflated entry per test input and answer; `files` gives each test's two host files in order.
/// A zip larger than `max_bytes` is refused.
pub fn write_result(
    tests: &[PlanTest],
    files: impl Fn(usize) -> (std::path::PathBuf, std::path::PathBuf),
    (dest, max_bytes): (&Path, u64),
) -> Result<(), GenerationFailure> {
    let mut writer = zip::ZipWriter::new(File::create(dest)?);
    for (position, test) in tests.iter().enumerate() {
        let (input, answer) = files(position);
        add_file(&mut writer, &test.input_name, &input)?;
        add_file(&mut writer, &test.answer_name, &answer)?;
    }
    writer.finish()?.flush()?;
    let size = std::fs::metadata(dest)?.len();
    if size > max_bytes {
        return Err(GenerationFailure::job(
            Kind::OutputLimit,
            format!("result zip is {size} bytes, over {max_bytes}"),
        ));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::super::plan::fixtures::generated;
    use super::*;
    use std::io::Read;

    #[test]
    fn the_budget_allows_exactly_its_total_and_refuses_more() {
        let mut budget = Budget::new(10);
        assert!(budget.charge(6).is_ok());
        assert!(budget.charge(4).is_ok());
        let failure = budget.charge(1).unwrap_err();
        assert_eq!((failure.kind, failure.test_index), (Kind::OutputLimit, 0));
        assert!(Budget::new(u64::MAX).charge(u64::MAX).is_ok());
    }

    #[test]
    fn the_zip_holds_each_input_and_answer_under_its_entry_name_and_respects_the_cap() {
        let dir = tempfile::tempdir().unwrap();
        let tests = vec![generated(1, "g"), generated(2, "g")];
        for (position, text) in ["a", "b", "c", "d"].iter().enumerate() {
            std::fs::write(dir.path().join(position.to_string()), text).unwrap();
        }
        let files = |position: usize| {
            (dir.path().join((position * 2).to_string()), dir.path().join((position * 2 + 1).to_string()))
        };
        let dest = dir.path().join("out.zip");
        write_result(&tests, files, (&dest, 1 << 20)).unwrap();
        let mut archive = zip::ZipArchive::new(File::open(&dest).unwrap()).unwrap();
        let mut read = |name: &str| {
            let mut text = String::new();
            archive.by_name(name).unwrap().read_to_string(&mut text).unwrap();
            text
        };
        assert_eq!([read("01.inp"), read("01.out"), read("02.inp"), read("02.out")], ["a", "b", "c", "d"]);
        let refused = write_result(&tests, files, (&dest, 10)).unwrap_err();
        assert_eq!(refused.kind, Kind::OutputLimit);
    }
}
